  "prediction_basis_card_ids": ["C21", "C51", "C37", "C32", "C50", "C48"],
  "claims": [
    {
      "claim": "The query is carbamazepine, a neutral lipophilic low-MW tricyclic urea; the closest gold-context analog thalidomide showed probably high absolute oral bioavailability (80–100%) at low doses in fasting volunteers, supporting F ≥ 20%.",
      "card_ids": ["C21"]
    },
    {
      "claim": "L4 provides direct intestinal absorption evidence for the same dibenzazepine carboxamide scaffold: oxcarbazepine absorption was essentially complete after a single oral radiolabeled dose in healthy volunteers, supporting high intestinal absorption for carbamazepine.",
      "card_ids": ["C51"]
    },
    {
      "claim": "Additional L4 records show complete or high human absorption for small aromatic molecules (salicylic acid 100%, phenylalanine 100%, D-Phe-L-Pro 100%, aminosalicylic acid essentially complete) and high permeability for cinnamic acid and tryptanthrin, consistent with favorable absorption of small lipophilic aromatic compounds.",
      "card_ids": ["C45", "C47", "C53", "C43", "C44", "C42", "C49", "C50", "C48"]
    },
    {
      "claim": "L3 oral exposure records show measurable systemic exposure after oral dosing of the carbamazepine scaffold, including carbamazepine-10,11-epoxide AUC12 of 9.98 µg·h/mL after oral carbamazepine 200 mg BID and fed-state Cmax of 12.8 µg/mL for the active metabolite of eslicarbazepine acetate.",
      "card_ids": ["C37", "C32"]
    },
    {
      "claim": "The low-solubility/dissolution records in L4 are for unrelated molecules (phenylalanine and OIB) and do not provide affirmative evidence against carbamazepine F ≥ 20%; no direct carbamazepine solubility or permeability measurement is present.",
      "card_ids": ["C52", "C46"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C51", "C50", "C48", "C45", "C47", "C53", "C49", "C42", "C43", "C44"]
    },
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C52", "C46"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for carbamazepine itself is supplied; C51 is oxcarbazepine absorption, not an F value.",
    "No fed-state-specific absorption or F record for carbamazepine; C32 is fed but for eslicarbazepine acetate metabolite exposure.",
    "No direct carbamazepine solubility, dissolution, or permeability measurement; L4 solubility records are for unrelated molecules.",
    "First-pass metabolism and systemic clearance are not quantified from the supplied records; carbamazepine is known to be metabolized, but no record establishes F < 20%.",
    "Most L1/L2 records are for other molecules or species, so transfer to the query is qualitative rather than direct."
  ],
  "decision_summary": "Prediction high: the query is carbamazepine, a neutral lipophilic low-MW tricyclic urea with favorable permeability; the closest analog thalidomide and other neutral amide/imide small molecules show F ≥ 29–100%, all above the 20% threshold. L4 adds essentially complete intestinal absorption for the close analog oxcarbazepine and high absorption/permeability records for related small aromatic molecules, strengthening the high prediction. No affirmative evidence supports F < 20%; fed-state and direct F measurements remain gaps."
}

